  const [playing, setPlaying] = useState(false); const [activeTrack, setActiveTrack] = useState<string | null>(null); const [menu, setMenu] = useState(false); const [filter, setFilter] = useState('All'); const [selected, setSelected] = useState<(typeof tracks)[number] | null>(null); const [lightbox, setLightbox] = useState<string | null>(null); const [activeString, setActiveString] = useState<number | null>(null)
  const audioRef = useRef<AudioContext | null>(null); const mediaRef = useRef<HTMLAudioElement | null>(null)
  const pluck = (frequency: number) => {
    const AudioCtor = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!audioRef.current && AudioCtor) audioRef.current = new AudioCtor()
    const ctx = audioRef.current; if (!ctx) return; if (ctx.state === 'suspended') void ctx.resume()
    const now = ctx.currentTime; const osc = ctx.createOscillator(); const body = ctx.createOscillator(); const gain = ctx.createGain(); const filterNode = ctx.createBiquadFilter()
    osc.type = 'sine'; body.type = 'triangle'; osc.frequency.setValueAtTime(frequency, now); body.frequency.setValueAtTime(frequency * 2.01, now)
    filterNode.type = 'lowpass'; filterNode.frequency.value = 1700; gain.gain.setValueAtTime(0.0001, now); gain.gain.exponentialRampToValueAtTime(.22, now + .008); gain.gain.exponentialRampToValueAtTime(.0001, now + 1.8)
    osc.connect(filterNode); body.connect(filterNode); filterNode.connect(gain); gain.connect(ctx.destination); osc.start(now); body.start(now); osc.stop(now + 2.2); body.stop(now + 2.2)
  }
